/** The core's GET routes under /api/v1, proxied by the shell as /api/exchange/<route>. */
export interface Routes {
  /** Counts for the sidebar: the whole library, Unidentified, and each environment's containers and types. */
  "sidebar": {
    path: {}
    query: {}
    response: Sidebar
  }
  /** Every environment with its roots (no counts; see the sidebar for those). */
  "environments": {
    path: {}
    query: {}
    response: Environment[]
  }
  /** A page of item cards, sorted by name (by type, then name, when grouped by type). */
  "dossiers": {
    path: {}
    query: {
      /** The search language, e.g. `donut env:starfield tag:food` */
      query?: string
      /** product, type or all; searches, type, collection and Unidentified views always list all, as the window does */
      group?: string
      /** Only assets with a live entry in this environment */
      environment?: number | null
      /** Only assets with a live entry in this container */
      container?: number | null
      /** Only this dossier type and its subtypes */
      type?: string | null
      /** One product's contents, by its uid */
      parent?: string | null
      /** One collection's members, by its uid */
      collection?: string | null
      /** Only Unidentified assets */
      unidentified?: boolean
      offset?: number
      limit?: number
    }
    response: Page
  }
  /** Everything the inspector shows for one asset, with its parent product's fields. */
  "dossiers/{uid}": {
    path: {
      uid: string
    }
    query: {}
    response: DossierDetail
  }
  /** An asset's thumbnail, from the thumbnail cache next to the database. */
  "dossiers/{uid}/thumbnail": {
    path: {
      uid: string
    }
    query: {}
    response: Blob
  }
  /** Manual and smart collections with their member counts. */
  "collections": {
    path: {}
    query: {}
    response: Collection[]
  }
  /** Every lexicon as scans use it: the file's terms, plus the words scans found (known authors). */
  "lexicons": {
    path: {}
    query: {}
    response: LexiconView[]
  }
  /** Pending suggestions, one page at a time, with counts by kind. */
  "suggestions": {
    path: {}
    query: {
      /** texture_link, variant_group or lexicon_word */
      kind?: string | null
      offset?: number
      limit?: number
    }
    response: Suggestions
  }
  /** Online roots, the desk's top level for unattached files (counts come per folder). */
  "desk/roots": {
    path: {}
    query: {}
    response: DeskRoot[]
  }
  /** One folder level of a root's unattached files: subfolders with counts, and files directly in it. */
  "desk/folders": {
    path: {}
    query: {
      root: number
      /** Root-relative, '/' separators */
      folder?: string
    }
    response: DeskLevel
  }
  /** Unattached files under a folder (all levels). */
  "desk/files": {
    path: {}
    query: {
      root: number
      folder?: string
      limit?: number
    }
    response: DeskFile[]
  }
  /** The library's edits, newest first (every session's, the window's included). */
  "history": {
    path: {}
    query: {
      offset?: number
      limit?: number
    }
    response: HistoryEntry[]
  }
  /** What Undo and Redo would do now. */
  "session": {
    path: {}
    query: {}
    response: Session
  }
  /** What editors offer: dossier types, the category tags, and the editable fields. */
  "choices": {
    path: {}
    query: {}
    response: Choices
  }
  /** Running jobs first, then the latest finished ones (without their reports). */
  "jobs": {
    path: {}
    query: {
      /** The list's version you have: wait for a newer one */
      since?: number | null
      /** Seconds to wait for a change */
      wait?: number
    }
    response: JobList
  }
  /** One job with its latest progress, and its report or result once it has ended. */
  "jobs/{job_id}": {
    path: {
      job_id: number
    }
    query: {
      /** The job's version you have: wait for a newer one */
      since?: number | null
      /** Seconds to wait for a change */
      wait?: number
    }
    response: Job
  }
  /** The environment definitions an environment can be of, for the add-environment wizard. */
  "environment-types": {
    path: {}
    query: {}
    response: EnvironmentType[]
  }
  /** Game, engine and content-library folders found on this PC (Steam, Epic, Unreal projects, Daz, MO2). Reads only where they are, never their files. */
  "environments/discover": {
    path: {}
    query: {}
    response: FoundSource[]
  }
  /** An MO2 instance's profiles and the one it has selected (folder names and its ini only). */
  "environments/mo2-profiles": {
    path: {}
    query: {
      /** An MO2 instance folder */
      folder: string
    }
    response: Mo2Profiles
  }
  /** One environment with its roots and settings. */
  "environments/{env_id}": {
    path: {
      env_id: number
    }
    query: {}
    response: EnvironmentDetail
  }
  /** Environments whose roots changed since they were last scanned (``available`` is false without ``watchdog``). A rescan of an environment clears it. */
  "changes": {
    path: {}
    query: {
      /** The version you have: wait for a newer one */
      since?: number | null
      /** Seconds to wait for a change */
      wait?: number
    }
    response: Changes
  }
  /** Every process package: trusted or not, its prerequisites (green or red with how to fix them), its options, and what trusting it allows. Only ready ones are offered for requisitions. */
  "processes": {
    path: {}
    query: {}
    response: ProcessList
  }
  /** Where the user said external tools are (Blender, texconv, Daz Studio...). */
  "tools": {
    path: {}
    query: {}
    response: Record<string, string>
  }
  /** Saved option sets: those shipped in packages, then the user's. */
  "presets": {
    path: {}
    query: {}
    response: PresetView[]
  }
  /** The options last queued with each process. */
  "presets/last-used": {
    path: {}
    query: {}
    response: Record<string, Record<string, unknown>>
  }
  /** Where requisitions write in each environment (Settings › Endpoints): the folder, whether the user chose it, and its visibility. Change them with ``/environments/{id}/config``. */
  "endpoints": {
    path: {}
    query: {}
    response: EndpointView[]
  }
  /** The queue (waiting or running, in order), then finished requisitions, newest first. */
  "requisitions": {
    path: {}
    query: {}
    response: RequisitionRow[]
  }
  /** One requisition: its items (with outputs) and every file it wrote. */
  "requisitions/{requisition_id}": {
    path: {
      requisition_id: number
    }
    query: {}
    response: RequisitionDetail
  }
}

/** The core's POST routes (edits), proxied as POST /api/exchange/<route> with a JSON body. */
export interface Posts {
  /** A manual collection, or a smart one (a saved search); new_uid is its uid. */
  "collections": {
    path: {}
    body: CollectionCreate
    response: EditResult
  }
  /** Set a field on one asset or many (bulk edit); a null value reverts to the scanned one. */
  "edits/fields": {
    path: {}
    body: FieldEdit
    response: EditResult
  }
  /** Add or remove tags on one asset or many. */
  "edits/tags": {
    path: {}
    body: TagEdit
    response: EditResult
  }
  /** Forget the user's choice about one tag (back to what scans found). */
  "edits/tags/revert": {
    path: {}
    body: TagRevert
    response: EditResult
  }
  /** Put assets into a product, or (parent null) take them out of any product. */
  "edits/parent": {
    path: {}
    body: ParentEdit
    response: EditResult
  }
  /** Revert Parent */
  "edits/parent/revert": {
    path: {}
    body: ParentRevert
    response: EditResult
  }
  /** The same asset found twice: `uid`'s entries and children join `into`. */
  "edits/merge": {
    path: {}
    body: MergeEdit
    response: EditResult
  }
  /** `uid` becomes a variant of `into`: one asset, two variants. */
  "edits/fold-variant": {
    path: {}
    body: FoldEdit
    response: EditResult
  }
  /** Entries wrongly grouped into an asset become an asset of their own (new_uid). */
  "edits/split": {
    path: {}
    body: SplitEdit
    response: EditResult
  }
  /** A variant becomes its own asset again (new_uid). */
  "edits/promote-variant": {
    path: {}
    body: PromoteEdit
    response: EditResult
  }
  /** A new product (new_uid) holding assets and/or a desk folder's unattached files. */
  "edits/products": {
    path: {}
    body: ProductEdit
    response: EditResult
  }
  /** Link files (or a desk folder's unattached files) onto an asset. */
  "edits/link-files": {
    path: {}
    body: LinkEdit
    response: EditResult
  }
  /** Unlink Files */
  "edits/unlink-files": {
    path: {}
    body: UnlinkEdit
    response: EditResult
  }
  /** Mark assets as not assets (out of Unidentified and default views), or count them again. */
  "edits/dismiss": {
    path: {}
    body: DismissEdit
    response: EditResult
  }
  /** Ignore a folder from now on: its unattached files leave the desk, and rescans skip it. */
  "edits/ignore-folder": {
    path: {}
    body: IgnoreEdit
    response: EditResult
  }
  /** Add assets to a manual collection, or (present false) remove them. */
  "collections/{uid}/members": {
    path: {
      uid: string
    }
    body: MembersEdit
    response: EditResult
  }
  /** Add a word to a lexicon term (written to the user's lexicon file), or remove it. Applies on the next rescan or classification. */
  "lexicons/{lexicon_id}/words": {
    path: {
      lexicon_id: string
    }
    body: WordEdit
    response: EditResult
  }
  /** Accept suggestions in one undoable step (the desk's batches). */
  "suggestions/accept": {
    path: {}
    body: SuggestionIds
    response: EditResult
  }
  /** Reject suggestions: they are not offered again. */
  "suggestions/reject": {
    path: {}
    body: SuggestionIds
    response: EditResult
  }
  /** Undo one history entry, from any session; the undo is itself undoable. */
  "history/{log_id}/undo": {
    path: {
      log_id: number
    }
    body: undefined
    response: EditResult
  }
  /** Undo this session's latest edit (label null when there is none). */
  "undo": {
    path: {}
    body: undefined
    response: UndoResult
  }
  /** Redo */
  "redo": {
    path: {}
    body: undefined
    response: UndoResult
  }
  /** Stop a running job (a scan keeps what it finished). */
  "jobs/{job_id}/stop": {
    path: {
      job_id: number
    }
    body: undefined
    response: Job
  }
  /** Detect the environments in a folder, register them and scan them (``exchange scan``). */
  "jobs/scan": {
    path: {}
    body: FolderJob
    response: Job
  }
  /** Which environments a folder holds, without reading any file (``exchange scan --dry-run``); nothing is written. The add-environment wizard's second step. */
  "jobs/detect": {
    path: {}
    body: FolderJob
    response: Job
  }
  /** Rescan known environments (all of them without ``environments``). */
  "jobs/rescan": {
    path: {}
    body: EnvironmentsJob
    response: Job
  }
  /** Classify the library again with the lexicons as they are now ("Apply to library" after lexicon edits); ``regroup`` also regroups hand-installed Daz products (after theme, author or category edits; minutes on a big library). */
  "jobs/classify": {
    path: {}
    body: ClassifyJob
    response: Job
  }
  /** Add environments (the wizard's third step): their roots and settings, and the folders never to index. Nothing is read from them until they are scanned (``/jobs/rescan`` with the ids). */
  "environments/register": {
    path: {}
    body: RegisterEnvironments
    response: Registered
  }
  /** Change an environment's settings: the fields given replace the ones it has (``exchange env config``). Ignore rules apply from the next rescan. */
  "environments/{env_id}/config": {
    path: {
      env_id: number
    }
    body: EnvironmentConfig
    response: ConfigResult
  }
  /** Trust a package as it is now: it may then run its own code. Ask the user first. */
  "processes/{process_id}/trust": {
    path: {
      process_id: string
    }
    body: undefined
    response: ProcessView
  }
  /** Copy a package folder into the user's processes folder; it stays untrusted until trusted. */
  "processes/install": {
    path: {}
    body: FolderJob
    response: ProcessView
  }
  /** Set a tool's path (null forgets it: manifests' likely paths are tried again). */
  "tools": {
    path: {}
    body: ToolPath
    response: Record<string, string>
  }
  /** Save options (by process) under a name; a user preset of that name is replaced. */
  "presets": {
    path: {}
    body: PresetSave
    response: PresetView
  }
  /** The chains of processes that take these assets (and products' children) into an environment: the dialog's route list (besides Automatic). */
  "requisitions/routes": {
    path: {}
    body: RoutesRequest
    response: RouteChoice[]
  }
  /** Plan getting assets into an environment (nothing is written): per asset, the items (a product's children too), each with its process chain, source and problems; the option forms for the processes in it; and warnings. */
  "requisitions/plan": {
    path: {}
    body: PlanRequest
    response: PlanResult
  }
  /** Plan this request again and queue every plan with something included; the options become each process's last used. Run them with ``/jobs/requisitions``. */
  "requisitions/queue": {
    path: {}
    body: PlanRequest
    response: Queued
  }
  /** Keep a queued requisition from running (``held`` false lets it run again). */
  "requisitions/{requisition_id}/hold": {
    path: {
      requisition_id: number
    }
    body: HoldRequest
    response: RequisitionDetail
  }
  /** Put a waiting requisition at a place in the queue (1 is first). */
  "requisitions/{requisition_id}/move": {
    path: {
      requisition_id: number
    }
    body: MoveRequest
    response: RequisitionDetail
  }
  /** Queue it again after a checkpoint or a collision (with how to settle collisions); failed items are retried. Run the queue to continue. */
  "requisitions/{requisition_id}/resume": {
    path: {
      requisition_id: number
    }
    body: ResumeRequest
    response: RequisitionDetail
  }
  /** Queue a fulfilled or stale requisition again with the current processes, overwriting its output; returns the new requisition. */
  "requisitions/{requisition_id}/rebuild": {
    path: {
      requisition_id: number
    }
    body: undefined
    response: RequisitionDetail
  }
  /** Mark fulfilled requisitions whose sources or processes changed as stale; the ones newly found. */
  "requisitions/check-stale": {
    path: {}
    body: undefined
    response: StaleRequisition[]
  }
  /** Run the queue (or some requisitions) in a worker process (``exchange requisition run``). */
  "jobs/requisitions": {
    path: {}
    body: RunRequest
    response: Job
  }
  /** Move what a requisition wrote to the recycle folder and put back what it overwrote, then rescan the folders it wrote to (``exchange requisition remove``). */
  "jobs/remove-output": {
    path: {}
    body: RemoveRequest
    response: Job
  }
}

/** The core's DELETE routes, proxied as DELETE /api/exchange/<route>. */
export interface Deletes {
  /** Delete Collection */
  "collections/{uid}": {
    path: {
      uid: string
    }
    body: undefined
    response: EditResult
  }
  /** Remove Preset */
  "presets/{name}": {
    path: {
      name: string
    }
    body: undefined
    response: PresetView[]
  }
}
